import sys

def main():
    n = int(sys.stdin.readline().strip())
    strings = []
    for _ in range(n):
        s = sys.stdin.readline().rstrip('\n')
        strings.append(s)

    sorted_strings = sorted(strings, key=lambda x: x.upper(), reverse=True)

    for s in sorted_strings:
        print(s.upper())

if __name__ == "__main__":
    main()
